let emailOtpReady=false,currentUser=null,editorDraft=null,liveReady=false;
const allAreas=['Maitama','Gwarinpa','Wuse','Garki','Jabi','Asokoro','Kubwa','Lokogoma','Lugbe','Utako','Jahi','Other Abuja area'];
async function api(path,options={}){const r=await fetch('/api'+path,{credentials:'same-origin',...options,headers:{'Content-Type':'application/json',...options.headers},body:options.body?JSON.stringify(options.body):undefined});let d;try{d=await r.json()}catch{throw new Error('The service could not be reached. Please try again.')}if(!r.ok)throw new Error(d.error?.message||d.error||d.message||'Please try again.');return d;}
function feedback(message){const e=$('#formError');if(e){e.textContent=message;e.hidden=false;e.scrollIntoView({block:'nearest'})}else toast(message)}
function busy(button,value,label){button.disabled=value;button.textContent=value?'Please wait…':label;}
function imageSrc(p){return p.photos?.[0]?.url|| (p.image?photo(p.image):'assets/fyield-logo.jpeg');}
async function refreshMarket(){const d=await api('/providers');drafts=d.profiles;liveReady=true;render();renderWork();$('#marketStatus').textContent=drafts.length?'Discover independent service providers across Abuja.':'Now welcoming service providers across Abuja.';}
async function session(){const d=await api('/session');currentUser=d.user;emailOtpReady=d.otpEnabled===true;$('#accountBtn').textContent=currentUser?'My account':'Sign in';}
function showAccount(mode='signin',after){
 if(currentUser&&!after){accountHome();return}
 if(emailOtpReady){otpAccount(after);return}
 openModal(`<div class="eyebrow">YOUR FYIELD ACCOUNT</div><h2>${mode==='signup'?'Make yourself at home.':'Welcome back.'}</h2><p>Sign in to manage your profile, send enquiries, and share a customer review.</p><form id="authForm">${mode==='signup'?'<label>Public display name<input name="name" required minlength="2" maxlength="70" autocomplete="nickname" placeholder="The name shown on your reviews"></label>':''}<label>Email address<input name="email" type="email" required autocomplete="email"></label><label>Password <small>At least 12 characters</small><input name="password" type="password" required minlength="12" maxlength="128" autocomplete="${mode==='signup'?'new-password':'current-password'}"></label><p id="formError" role="alert" class="form-error" hidden></p><button class="btn dark">${mode==='signup'?'Create account':'Sign in'} →</button></form><button class="text-link auth-switch" id="switchAuth">${mode==='signup'?'Already have an account? Sign in':'New to Fyield? Create an account'}</button><p class="fine-print">Your email is private. Your display name appears on public reviews. Keep your password safe; email-based recovery is not available yet.</p>`);
 $('#switchAuth').onclick=()=>showAccount(mode==='signup'?'signin':'signup',after);
 $('#authForm').onsubmit=async e=>{e.preventDefault();const b=e.submitter;busy(b,true);try{const body=Object.fromEntries(new FormData(e.target));await api('/auth/'+(mode==='signup'?'sign-up/email':'sign-in/email'),{method:'POST',body});await session();await refreshMarket();if(after)after();else accountHome()}catch(err){feedback(err.message);busy(b,false,mode==='signup'?'Create account':'Sign in')}};
}
function accountHome(){openModal(`<div class="eyebrow">YOUR ACCOUNT</div><h2>Hello, ${esc(currentUser.name)}.</h2><p>${esc(currentUser.email)}</p><div class="account-actions"><button class="btn dark" id="myProfile">Manage my service profile ↗︎</button><button class="btn outline" id="myMessages">My enquiries →</button><button class="btn outline" id="photoLibraryBtn">Manage uploaded photos</button>${emailOtpReady?'':'<button class="btn outline" id="passwordBtn">Change password</button>'}${currentUser.isAdmin?'<button class="btn dark" id="adminBtn">Admin dashboard ↗︎</button>':''}<button class="text-link" id="signout">Sign out</button></div>`);$('#myProfile').onclick=()=>editProvider();$('#myMessages').onclick=inbox;if($('#passwordBtn'))$('#passwordBtn').onclick=changePassword;if($('#adminBtn'))$('#adminBtn').onclick=adminDashboard;$('#photoLibraryBtn').onclick=photoLibrary;$('#signout').onclick=async()=>{try{await api('/auth/sign-out',{method:'POST',body:{}});currentUser=null;editorDraft=null;$('#accountBtn').textContent='Sign in';$('#modal').close();await refreshMarket()}catch(e){toast(e.message)}};}
function changePassword(){openModal(`<h2>Change your password</h2><form id="passwordForm"><label>Current password<input name="currentPassword" type="password" required autocomplete="current-password"></label><label>New password<input name="newPassword" type="password" required minlength="12" maxlength="128" autocomplete="new-password"></label><p id="formError" role="alert" class="form-error" hidden></p><button class="btn dark">Update password</button></form>`);$('#passwordForm').onsubmit=async e=>{e.preventDefault();try{await api('/auth/change-password',{method:'POST',body:{...Object.fromEntries(new FormData(e.target)),revokeOtherSessions:true}});accountHome();toast('Password changed. Other sessions were signed out.')}catch(err){feedback(err.message)}};}
function captureEditor(){const f=$('#providerForm');if(!f)return editorDraft;const d=Object.fromEntries(new FormData(f));editorDraft={...editorDraft,...d,skills:d.skills.split(',').map(s=>s.trim()).filter(Boolean),consent:f.elements.consent.checked,photos:editorDraft.photos.map((p,i)=>({...p,caption:$('#caption'+i)?.value||p.caption||''}))};return editorDraft;}
async function editProvider(resume=false){
 if(!resume){editorDraft=null;if(currentUser){try{editorDraft=(await api('/my-profile')).profile}catch(e){toast(e.message);return}}}
 editorDraft ||= {name:'',title:'',category:'Cleaning',area:'Wuse',about:'',price:'',unit:'visit',experience:0,skills:[],photos:[]};
 const p=editorDraft;
 openModal(`<div class="editor-heading"><div><div class="eyebrow">FOR ABUJA’S DOERS & MAKERS</div><h2>${p.id?'Make your profile shine.':'Let your work introduce you.'}</h2><p>Tell people what you do. Show them how well you do it.</p></div><span class="pill editor-pill">${p.id?'EDIT PROFILE':'NEW PROVIDER'}</span></div><form id="providerForm"><div class="editor-columns"><div><section class="form-section"><h3><span>01</span> The essentials</h3><div class="two-fields"><label>Business or professional name<input name="name" value="${esc(p.name)}" required minlength="2" maxlength="70" placeholder="How customers know you"></label><label>Service category<select name="category">${categories.map(([c])=>`<option ${p.category===c?'selected':''}>${c}</option>`).join('')}</select></label></div><label>Your headline<input name="title" value="${esc(p.title)}" required minlength="8" maxlength="100" placeholder="e.g. Reliable deep cleaning for Abuja homes"></label><div class="two-fields"><label>Abuja neighborhood<select name="area">${allAreas.map(a=>`<option ${p.area===a?'selected':''}>${a}</option>`).join('')}</select></label><label>Years of experience<input name="experience" type="number" value="${esc(p.experience)}" required min="0" max="60"></label></div></section><section class="form-section"><h3><span>02</span> What you bring to the job</h3><label>About your service<textarea name="about" required minlength="40" maxlength="2000" placeholder="Describe your experience, the jobs you take on, and what a customer can expect.">${esc(p.about)}</textarea></label><label>Services you offer <small>Separate with commas · up to 8</small><input name="skills" required maxlength="360" value="${esc(p.skills.join(', '))}" placeholder="Deep cleaning, Move-in cleaning, Office cleaning"></label><div class="two-fields"><label>Starting price (₦)<input name="price" type="number" min="100" max="10000000" required value="${esc(p.price)}"></label><label>Per<select name="unit">${['hour','day','visit','session','service','job'].map(u=>`<option ${u===p.unit?'selected':''}>${u}</option>`).join('')}</select></label></div></section></div><section class="form-section photo-section"><h3><span>03</span> The work behind your skill</h3><p>Add up to six photos. Describe the work in each image so customers understand what you delivered.</p><div id="editorPhotos" class="editor-photos"></div><label class="upload-zone" for="workPhotos"><strong>＋ Add work photos</strong><span>JPG, PNG or WebP · up to 8 MB each</span><input id="workPhotos" type="file" accept="image/jpeg,image/png,image/webp" multiple></label><p class="fine-print">Only share work you have permission to show. Do not include children, identity documents, private home addresses, or customer contact details.</p><p id="photoStatus" role="status"></p></section></div><label class="check-label"><input name="consent" type="checkbox" required ${p.consent?'checked':''}><span>I confirm these details are accurate and I have permission to publish the photos and captions. My profile and work gallery will be public.</span></label><p id="formError" class="form-error" role="alert" hidden></p><div class="editor-footer"><p>${currentUser?'Your email stays private. Changes are saved when you publish.':'You can fill this in now. Sign in to publish and save across devices.'}</p><button class="btn dark" type="submit">${p.id?'Save profile changes':'Publish my profile'} ↗︎</button></div></form>${p.id?'<button id="unpublish" class="text-link danger">Remove my public profile</button>':''}`);
 $('#modal').classList.add('wide');renderEditorPhotos();
 $('#workPhotos').onchange=async e=>{captureEditor();const files=[...e.target.files];if(editorDraft.photos.length+files.length>6){feedback('Choose up to six photos in total.');return}$('#photoStatus').textContent='Preparing photos…';const b=$('#providerForm button[type=submit]');b.disabled=true;try{for(const f of files){if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>8*1024*1024)throw new Error('Choose JPG, PNG, or WebP photos up to 8 MB each.');const data=await compressImage(f);editorDraft.photos.push({local:data,url:data,caption:''});}renderEditorPhotos();$('#photoStatus').textContent='Photos ready. Add a caption for each one.'}catch(err){feedback(err.message)}finally{b.disabled=false;e.target.value=''}};
 $('#providerForm').onsubmit=async e=>{e.preventDefault();captureEditor();if(editorDraft.skills.length>8){feedback('Please use no more than eight services.');return}if(!currentUser){showAccount('signup',()=>editProvider(true));return}const b=e.submitter;busy(b,true);try{for(const p of editorDraft.photos){if(p.local){const d=await api('/photos',{method:'POST',body:{image:p.local,consent:true}});p.id=d.photo.id;p.url=d.photo.url;delete p.local;}}const d=await api('/providers',{method:'POST',body:editorDraft});editorDraft=null;await refreshMarket();await details(d.profile.id);toast('Your profile is live.')}catch(err){feedback(err.message);busy(b,false,'Publish profile')}};
 if(p.id)$('#unpublish').onclick=()=>confirmRemoveProfile();
}
async function compressImage(file){const bitmap=await createImageBitmap(file);if(bitmap.width*bitmap.height>20000000){bitmap.close();throw new Error('Choose a photo smaller than 20 megapixels.')}const ratio=Math.min(1,1400/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*ratio);canvas.height=Math.round(bitmap.height*ratio);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const data=canvas.toDataURL('image/jpeg',.8);if(data.length>1800000)throw new Error('This photo is too large. Try a smaller image.');return data;}
function renderEditorPhotos(){$('#editorPhotos').innerHTML=editorDraft.photos.map((p,i)=>`<div class="editor-photo"><img src="${esc(p.url)}" alt="Your work photo ${i+1}"><div><label for="caption${i}">What did you do here?</label><textarea id="caption${i}" required minlength="8" maxlength="180" placeholder="e.g. Full deep clean of a two-bedroom apartment in Wuse">${esc(p.caption||'')}</textarea><button type="button" class="text-link" data-remove-photo="${i}">Remove photo</button></div></div>`).join('');document.querySelectorAll('[data-remove-photo]').forEach(b=>b.onclick=()=>{captureEditor();editorDraft.photos.splice(Number(b.dataset.removePhoto),1);renderEditorPhotos()});}
function confirmRemoveProfile(){openModal(`<h2>Remove your public profile?</h2><p>Your listing, its reviews, and its enquiries will be removed. Your account and uploaded photos remain available.</p><div class="modal-actions"><button class="btn outline" id="keepProfile">Keep profile</button><button class="btn dark" id="removeProfile">Remove profile</button></div>`);$('#keepProfile').onclick=()=>editProvider();$('#removeProfile').onclick=async()=>{try{await api('/providers/me',{method:'DELETE',body:{}});editorDraft=null;await refreshMarket();accountHome();toast('Your public profile was removed.')}catch(e){toast(e.message)}};}
async function details(id){
 const sample=typeof id==='number';let p=profiles.find(p=>p.id===id)||drafts.find(p=>p.id===id);if(!sample){try{p=(await api('/providers/'+id)).profile}catch(e){toast(e.message);return}}if(!p)return;
 const gallery=sample?[{url:photo(p.image),caption:'Sample photograph. This is not evidence of this illustrative provider’s work.'}]:(p.photos||[]);
 openModal(`<div class="profile-layout"><aside class="portfolio-side"><div class="eyebrow">${sample?'SAMPLE PHOTOGRAPH':'WORK GALLERY'}</div>${gallery.length?`<div class="portfolio-main"><img id="galleryMain" src="${esc(gallery[0].url)}" alt="${esc(gallery[0].caption)}"></div><p id="galleryCaption" class="gallery-caption">${esc(gallery[0].caption)}</p><div class="gallery-thumbs">${gallery.map((g,i)=>`<button data-gallery="${i}" class="${i===0?'chosen':''}" aria-label="View work photo ${i+1}"><img src="${esc(g.url)}" alt="${esc(g.caption)}"></button>`).join('')}</div>`:'<div class="gallery-empty"><span>▧</span><h3>Every skill has a story.</h3><p>This provider hasn’t added work photos yet.</p></div>'}</aside><div class="profile-info"><div class="eyebrow">${esc(p.category)} · ABUJA</div><h2>${esc(p.name)}</h2><p class="profile-headline">${esc(p.title)}</p><div class="profile-facts"><span>⌖ ${esc(p.area)}</span>${!sample?`<span>${p.experience} years’ experience</span>`:''}<span>${p.reviewCount?`★ ${p.rating} · ${p.reviewCount} reviews`:'☆ No reviews yet'}</span></div><div class="profile-price"><div><span>Starting from</span><strong>₦${Number(p.price).toLocaleString()} <small>/ ${esc(p.unit)}</small></strong></div>${!sample&&p.isOwn?'<button class="btn outline" id="editOwn">Edit profile ↗︎</button>':`<button class="btn dark" id="contactProvider" ${sample?'disabled':''}>${sample?'Example profile':'Send enquiry ↗︎'}</button>`}</div><section class="profile-section"><h3>Meet your helping hand</h3><p>${esc(p.about)}</p></section><section class="profile-section"><h3>Services offered</h3><ul class="service-tags">${p.skills.map(s=>`<li>${esc(s)}</li>`).join('')}</ul></section>${sample?'<p class="notice">Example profile and pricing, shown to demonstrate Fyield. This person is not available for contact or review.</p>':''}<section class="profile-section"><div class="reviews-heading"><h3>Customer reviews</h3>${!sample&&!p.isOwn?'<button class="text-link" id="writeReview">Write a review ↗︎</button>':''}</div><div id="reviewList" data-profile="${esc(p.id)}"><div class="review-empty"><span>☆ ☆ ☆ ☆ ☆</span><h4>No reviews yet</h4><p>Honest feedback starts with a real experience.</p></div></div><p class="fine-print">Reviews are posted by account holders who confirm they used the service. Fyield has not independently verified their bookings.</p></section></div></div>`);
 $('#modal').classList.add('wide');document.querySelectorAll('[data-gallery]').forEach(b=>b.onclick=()=>{const g=gallery[Number(b.dataset.gallery)];$('#galleryMain').src=g.url;$('#galleryMain').alt=g.caption;$('#galleryCaption').textContent=g.caption;document.querySelectorAll('[data-gallery]').forEach(x=>x.classList.toggle('chosen',x===b))});
 if($('#editOwn'))$('#editOwn').onclick=()=>editProvider();if($('#contactProvider'))$('#contactProvider').onclick=()=>sample?enquiry(p):contact(p);if($('#writeReview'))$('#writeReview').onclick=()=>reviewForm(p);
 if(!sample){try{const d=await api('/providers/'+p.id+'/reviews');if(!$('#reviewList')||$('#reviewList').dataset.profile!==String(p.id))return;if(d.reviews.length)$('#reviewList').innerHTML=d.reviews.map(r=>`<article class="review"><div><strong>${esc(r.name)}</strong><span class="stars" aria-label="${r.rating} out of 5 stars">${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)}</span></div><p>${esc(r.comment)}</p><small>${new Date(r.createdAt).toLocaleDateString('en-NG',{day:'numeric',month:'short',year:'numeric'})}</small>${r.isOwn?`<button class="text-link" data-delete-review="${r.id}">Remove my review</button>`:''}</article>`).join('');document.querySelectorAll('[data-delete-review]').forEach(b=>b.onclick=async()=>{try{await api('/reviews/'+b.dataset.deleteReview,{method:'DELETE',body:{}});await refreshMarket();details(p.id)}catch(e){toast(e.message)}})}catch(e){if($('#reviewList'))$('#reviewList').textContent='Reviews could not be loaded. Close and reopen this profile to retry.'}}
}
function reviewForm(p){if(!currentUser){showAccount('signin',()=>reviewForm(p));return}openModal(`<div class="eyebrow">YOUR EXPERIENCE MATTERS</div><h2>Review ${esc(p.name)}</h2><p>Share specific, fair feedback about a service you personally received.</p><form id="reviewForm"><fieldset class="rating-picker"><legend>Your rating</legend>${[1,2,3,4,5].map(n=>`<label><input type="radio" name="rating" value="${n}" required><span>${n} ★</span></label>`).join('')}</fieldset><label>Your experience<textarea name="comment" required minlength="20" maxlength="1200" placeholder="What work was done? What went well, and what could be improved?"></textarea></label><label class="check-label"><input name="confirmed" type="checkbox" required><span>I personally used this provider’s service. This review is honest and contains no private information.</span></label><p class="fine-print">Your display name and review will be public. One review per account, per provider.</p><p id="formError" role="alert" class="form-error" hidden></p><button class="btn dark">Publish review →</button></form>`);$('#reviewForm').onsubmit=async e=>{e.preventDefault();const b=e.submitter;busy(b,true);try{const v=Object.fromEntries(new FormData(e.target));await api('/providers/'+p.id+'/reviews',{method:'POST',body:{...v,confirmed:true}});await refreshMarket();await details(p.id);toast('Your review is published.')}catch(err){feedback(err.message);busy(b,false,'Publish review')}};}
function contact(p){if(!currentUser){showAccount('signin',()=>contact(p));return}openModal(`<div class="eyebrow">START A CONVERSATION</div><h2>Enquire with ${esc(p.name)}</h2><p>Describe what you need and your preferred timing. This is an enquiry, not a confirmed booking.</p><form id="contactForm"><label>Your message<textarea name="message" required minlength="20" maxlength="1500" placeholder="Tell the provider about the job and your Abuja neighborhood."></textarea></label><p class="fine-print">Only you and this provider can see this message. Avoid sharing children’s details, identity documents, payment information, or exact home addresses.</p><p id="formError" role="alert" class="form-error" hidden></p><button class="btn dark">Send enquiry →</button></form>`);$('#contactForm').onsubmit=async e=>{e.preventDefault();const b=e.submitter;busy(b,true);try{await api('/providers/'+p.id+'/enquiries',{method:'POST',body:Object.fromEntries(new FormData(e.target))});await inbox();toast('Enquiry sent. Check My enquiries for a reply.')}catch(err){feedback(err.message);busy(b,false,'Send enquiry')}};}
async function inbox(){if(!currentUser){showAccount('signin',inbox);return}try{const d=await api('/enquiries');openModal(`<div class="eyebrow">PRIVATE CONVERSATIONS</div><h2>My enquiries</h2><p>Replies appear here. Email notifications are not enabled.</p><div class="enquiry-list">${d.enquiries.length?d.enquiries.map(q=>`<article class="enquiry"><h3>${esc(q.canReply?q.customerName:q.providerName)}</h3><small>${new Date(q.createdAt).toLocaleDateString('en-NG')}</small><p>${esc(q.message)}</p>${q.reply?`<div class="reply"><b>Provider’s reply</b><p>${esc(q.reply)}</p></div>`:''}${q.canReply?`<button class="text-link" data-reply="${q.id}">${q.reply?'Update reply':'Reply to enquiry'} →</button>`:''}</article>`).join(''):'<div class="review-empty"><h3>No enquiries yet.</h3><p>Your service conversations will appear here.</p></div>'}</div>`);document.querySelectorAll('[data-reply]').forEach(b=>b.onclick=()=>replyForm(b.dataset.reply))}catch(e){toast(e.message)}}
function replyForm(id){openModal(`<h2>Reply to enquiry</h2><form id="replyForm"><label>Your reply<textarea name="reply" required minlength="10" maxlength="1500"></textarea></label><p id="formError" role="alert" class="form-error" hidden></p><button class="btn dark">Send reply →</button></form>`);$('#replyForm').onsubmit=async e=>{e.preventDefault();try{await api('/enquiries/'+id+'/reply',{method:'POST',body:Object.fromEntries(new FormData(e.target))});inbox()}catch(err){feedback(err.message)}};}
$('#accountBtn').onclick=()=>showAccount();
Promise.all([session(),refreshMarket()]).then(()=>{if(location.hash==='#admin')openAdminAccess()}).catch(()=>{$('#marketStatus').textContent='Community profiles could not be loaded. Please refresh to retry.'});

async function photoLibrary(){try{const d=await api('/my-photos');openModal(`<div class="eyebrow">YOUR UPLOADS</div><h2>Photo library</h2><p>Photos in a published profile must be removed from that profile and saved before you can delete them here.</p><div class="photo-library">${d.photos.length?d.photos.map(p=>`<article><img src="${esc(p.url)}" alt="Your uploaded work"><button class="text-link" data-delete-photo="${p.id}">Delete unused photo</button></article>`).join(''):'<p>No uploaded photos yet.</p>'}</div>`);document.querySelectorAll('[data-delete-photo]').forEach(b=>b.onclick=async()=>{try{await api('/photos/'+b.dataset.deletePhoto,{method:'DELETE',body:{}});photoLibrary();toast('Photo deleted.')}catch(e){toast(e.message)}})}catch(e){toast(e.message)}}

function renderWork(){const work=drafts.flatMap(p=>(p.photos||[]).map(photo=>({...photo,provider:p}))).slice(0,6);$('#work').hidden=!work.length;$('#workGrid').innerHTML=work.map(w=>`<button class="work-card" data-work="${esc(w.provider.id)}"><div class="work-photo"><img src="${esc(w.url)}" alt="${esc(w.caption)}" loading="lazy"></div><h3>${esc(w.caption)} ↗︎</h3><p>${esc(w.provider.category)} · ${esc(w.provider.name)}</p></button>`).join('');document.querySelectorAll('[data-work]').forEach(b=>b.onclick=()=>details(b.dataset.work));}

function otpAccount(after){
 openModal(`<div class="eyebrow">YOUR FYIELD ACCOUNT</div><h2>Continue with email.</h2><p>We’ll send a six-digit code to your inbox. Gmail and other email addresses are welcome.</p><form id="otpStart"><label>Public display name<input name="name" required minlength="2" maxlength="70" autocomplete="nickname"></label><label>Email address<input name="email" type="email" required autocomplete="email"></label><p id="formError" class="form-error" role="alert" hidden></p><button class="btn dark">Send my code →</button></form><p class="fine-print">Your email stays private. Your display name appears on reviews. Existing accounts keep their current display name.</p>`);
 $('#otpStart').onsubmit=async e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target));busy(e.submitter,true);try{await api('/auth/email-otp/send-verification-otp',{method:'POST',body:{email:values.email,type:'sign-in'}});otpCode(values,after)}catch(err){feedback(err.message);busy(e.submitter,false,'Send my code →')}};
}
function otpCode(values,after){
 openModal(`<div class="eyebrow">CHECK YOUR INBOX</div><h2>Enter your code.</h2><p>We sent a code to <strong>${esc(values.email)}</strong>. It expires in five minutes.</p><form id="otpCheck"><label>Six-digit code<input name="otp" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" minlength="6" maxlength="6" required></label><p id="formError" class="form-error" role="alert" hidden></p><button class="btn dark">Verify and continue →</button></form><button class="text-link" id="resendOtp">Send a new code</button><button class="text-link" id="changeOtpEmail">Use a different email</button>`);
 $('#otpCheck').onsubmit=async e=>{e.preventDefault();const b=e.submitter;busy(b,true);try{await api('/auth/sign-in/email-otp',{method:'POST',body:{...values,otp:new FormData(e.target).get('otp')}});await session();await refreshMarket();if(after)after();else accountHome()}catch(err){feedback(err.message);busy(b,false,'Verify and continue →')}};
 $('#changeOtpEmail').onclick=()=>otpAccount(after);
 $('#resendOtp').onclick=async e=>{busy(e.target,true);try{await api('/auth/email-otp/send-verification-otp',{method:'POST',body:{email:values.email,type:'sign-in'}});toast('A new code has been sent.')}catch(err){feedback(err.message)}finally{busy(e.target,false,'Send a new code')}};
}
async function adminDashboard(page=0){
 try{const d=await api('/admin/overview?page='+page);openModal(`<div class="eyebrow">FYIELD ADMINISTRATION</div><h2>Your community, at a glance.</h2><p>Restricted to approved, email-verified administrators.</p><div class="admin-counts">${Object.entries(d.counts).map(([k,v])=>`<div><strong>${v}</strong><span>${esc(k)}</span></div>`).join('')}</div><h3>Accounts</h3><div class="admin-table"><table><thead><tr><th>Name</th><th>Email</th><th>Verified</th></tr></thead><tbody>${d.users.map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.email)}</td><td>${u.verified?'Yes':'No'}</td></tr>`).join('')}</tbody></table></div><h3>Provider profiles</h3><div class="admin-table"><table><thead><tr><th>Provider</th><th>Service</th><th>Area</th><th>Email</th></tr></thead><tbody>${d.providers.map(p=>`<tr><td>${esc(p.name)}</td><td>${esc(p.category)}</td><td>${esc(p.area)}</td><td>${esc(p.email)}</td></tr>`).join('')}</tbody></table></div><h3>Recent reviews</h3>${d.reviews.map(r=>`<article class="review"><strong>${esc(r.customer)} → ${esc(r.provider)} · ${r.rating}/5</strong><p>${esc(r.comment)}</p></article>`).join('')||'<p>No reviews yet.</p>'}<p class="fine-print">Private messages, passwords, session tokens and verification codes are not shown. Each page contains up to 25 records per section.</p><div class="modal-actions"><button class="btn outline" id="adminPrev" ${page===0?'disabled':''}>Previous</button><span>Page ${page+1}</span><button class="btn outline" id="adminNext" ${Math.max(d.counts.accounts,d.counts.providers,d.counts.reviews)<=(page+1)*25?'disabled':''}>Next</button></div>`);$('#modal').classList.add('wide');$('#adminPrev').onclick=()=>adminDashboard(page-1);$('#adminNext').onclick=()=>adminDashboard(page+1)}catch(e){toast(e.message)}
}

function openAdminAccess(){
 if(!currentUser){showAccount('signin',openAdminAccess);return}
 if(currentUser.isAdmin){adminDashboard();return}
 openModal('<div class="eyebrow">ADMIN ACCESS</div><h2>Restricted dashboard.</h2><p>This account needs an approved administrator email and verified email ownership.</p><p>If you are the administrator, sign in with your approved email. Email verification becomes available once delivery is configured.</p><button class="btn outline" id="adminAccount">My account</button>');
 $('#adminAccount').onclick=accountHome;
}
window.addEventListener('hashchange',()=>{if(location.hash==='#admin')openAdminAccess()});
